                KeybindBox.TextSize = 11
                KeybindBox.BackgroundTransparency = 1
                KeybindBox.LayoutOrder = 2;
                KeybindBox.Parent = RightContainer
            
                local KeybindButton = Instance.new("TextButton")
                KeybindButton.Size = UDim2.new(1, 0, 1, 0)
                KeybindButton.BackgroundTransparency = 1
                KeybindButton.TextTransparency = 1
                KeybindButton.Parent = KeybindBox

                local CheckboxCorner = Instance.new("UICorner", KeybindBox)
                CheckboxCorner.CornerRadius = UDim.new(0, 3)

                local UIStroke = Instance.new("UIStroke", KeybindBox)
                UIStroke.Color = Color3.fromRGB(255, 255, 255)
                UIStroke.Thickness = 1
                UIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            
                if not Library._config._flags then
                    Library._config._flags = {}
                end
            
                if not Library._config._flags[settings.flag] then
                    Library._config._flags[settings.flag] = {
                        checked = false,
                        BIND = settings.default or "Unknown"
                    }
                end
            
                checked = Library._config._flags[settings.flag].checked
                KeybindBox.Text = Library._config._flags[settings.flag].BIND

                if KeybindBox.Text == "Unknown" then
                    KeybindBox.Text = "...";
                end;

                local UseF_Var = nil;
            
                if not settings.disablecheck then
                    local Checkbox = Instance.new("TextButton")
                    Checkbox.Size = UDim2.new(0, 15, 0, 15)
                    Checkbox.BackgroundColor3 = checked and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(20, 20, 20)
                    Checkbox.Text = ""
                    Checkbox.Parent = RightContainer
                    Checkbox.LayoutOrder = 1;

                    local UIStroke = Instance.new("UIStroke", Checkbox)
                    UIStroke.Color = Color3.fromRGB(255, 255, 255)
                    UIStroke.Thickness = 1
                    UIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                
                    local CheckboxCorner = Instance.new("UICorner")
                    CheckboxCorner.CornerRadius = UDim.new(0, 3)
                    CheckboxCorner.Parent = Checkbox
            
                    local function toggleState()
                        checked = not checked
                        Checkbox.BackgroundColor3 = checked and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(20, 20, 20)
                        Library._config._flags[settings.flag].checked = checked
                        Config:save(game.GameId, Library._config)
                        if settings.callback then
                            settings.callback(checked)
                        end
                    end

                    UseF_Var = toggleState
                
                    Checkbox.MouseButton1Click:Connect(toggleState)

                else

                    UseF_Var = function()
                        settings.button_callback();
                    end;

                end;
            
                KeybindButton.MouseButton1Click:Connect(function()
                    KeybindBox.Text = "..."
                    local inputConnection
                    inputConnection = game:GetService("UserInputService").InputBegan:Connect(function(input, gameProcessed)
                        if gameProcessed then return end
                        if input.UserInputType == Enum.UserInputType.Keyboard then
                            local newKey = input.KeyCode.Name
                            Library._config._flags[settings.flag].BIND = newKey
                            if newKey ~= "Unknown" then
                                KeybindBox.Text = newKey;
                            end;
                            Config:save(game.GameId, Library._config) -- Save new keybind
                            inputConnection:Disconnect()
                        elseif input.UserInputType == Enum.UserInputType.MouseButton3 then
                            Library._config._flags[settings.flag].BIND = "Unknown"
                            KeybindBox.Text = "..."
                            Config:save(game.GameId, Library._config)
                            inputConnection:Disconnect()
                        end
                    end)
                    Connections["keybind_input_" .. settings.flag] = inputConnection
                end)
            
                local keyPressConnection
                keyPressConnection = game:GetService("UserInputService").InputBegan:Connect(function(input, gameProcessed)
                    if gameProcessed then return end
                    if input.UserInputType == Enum.UserInputType.Keyboard then
                        if input.KeyCode.Name == Library._config._flags[settings.flag].BIND then
                            UseF_Var();
                        end
                    end
                end)
                Connections["keybind_press_" .. settings.flag] = keyPressConnection
            
                FeatureButton.MouseButton1Click:Connect(function()
                    if settings.button_callback then
                        settings.button_callback()
                    end
                end)

                if not settings.disablecheck then
                    settings.callback(checked);
                end;
            
                return FeatureContainer
            end                    

            return ModuleManager
        end

        return TabManager
    end

    Connections['library_visiblity'] = UserInputService.InputBegan:Connect(function(input: InputObject, process: boolean)
        if process or UserInputService:GetFocusedTextBox() then
            return
        end

        if input.KeyCode ~= Enum.KeyCode.Insert and input.KeyCode ~= Enum.KeyCode.LeftControl then
            return
        end

        if self._ui and not self._ui.Enabled then
            self._ui.Enabled = true
            self._ui_open = true
            self:change_visiblity(true)
            return
        end

        self._ui_open = not self._ui_open
        self:change_visiblity(self._ui_open)
    end)

    self._ui.Container.Handler.Minimize.MouseButton1Click:Connect(function()
        self._ui_open = not self._ui_open
        self:change_visiblity(self._ui_open)
    end)

    return self
end

return Library
end)()

local Library = (function()
    local Library = {}
    local TAB_ICONS = {
        Main    = { id = "rbxassetid://16898787671", offset = Vector2.new(257, 514), size = Vector2.new(256, 256) },
        Blatant = "rbxassetid://7734058599", Spam = "rbxassetid://7733955740",
        Detection = "rbxassetid://7734056608", Player = "rbxassetid://7743875962",
        Visual = "rbxassetid://7733774602", Misc = "rbxassetid://7733917120",
        World = "rbxassetid://7733954760", GUI = "rbxassetid://7734053495",
        Config = "rbxassetid://7734052335", Unlock = "rbxassetid://7733965118",
    }
    local FALLBACK = "rbxassetid://7733919881"
    local NOP = function() end
    local function stub() return { update=NOP,SetValue=NOP,change_state=NOP,set_options=NOP,set_percentage=NOP,SetVisible=NOP,Set=NOP,update_text=NOP } end
    local function norm(i)
        i = i or {}
        if i.options == nil then i.options = i.values end
        if i.minimum_value == nil then i.minimum_value = i.minimum end
        if i.maximum_value == nil then i.maximum_value = i.maximum end
        if i.value == nil then i.value = i.default end
        if i.callback == nil then i.callback = NOP end
        return i
    end
    function Library.SendNotification(info)
        info = info or {}
        pcall(function() AilonUI.SendNotification({ title=tostring(info.title or info.Title or "UI"), text=tostring(info.text or info.description or info.Content or ""), duration=tonumber(info.duration or info.time or info.Duration) or 4 }) end)
    end
    function Library.new(config)
        config = config or {}
        local main = AilonUI.new()
        local win = { _native = main }
        pcall(function() win._ui = main._ui end)
        win._notification_helpers = { theme = { accent = Color3.fromRGB(48,92,200), info = Color3.fromRGB(48,92,200), radius = UDim.new(0,6) } }
        function win:create_tab(name, icon)
            local nm = tostring(name or "Tab")
            local ic = icon or TAB_ICONS[nm] or FALLBACK
            local okT, Tab = pcall(function() return main:create_tab(nm, ic) end)
            if not okT then Tab = nil end
            local tab = { _tab = Tab }
            local sideFlip = "left"
            function tab:create_module(info)
                info = info or {}
                if info.section == nil then info.section = sideFlip; sideFlip = (sideFlip=="left") and "right" or "left" end
                if info.callback == nil then info.callback = NOP end
                local M = nil
                if Tab then local ok, r = pcall(function() return Tab:create_module(info) end); if ok then M = r end end
                local mod = { _m = M }
                function mod:change_state(a,b) local v=(b~=nil) and b or a; pcall(function() if M then M:change_state(v and true or false) end end) end
                function mod:update(v) pcall(function() if M then M:change_state(v and true or false) end end) end
                function mod:SetValue(v) pcall(function() if M then M:change_state(v and true or false) end end) end
                function mod:create_checkbox(i) i=norm(i); if not M then return stub() end local ok,cb=pcall(function() return M:create_checkbox(i) end); if not ok or not cb then return stub() end cb.update=function(_,v) pcall(function() cb:change_state(v and true or false) end) end cb.SetValue=cb.update return cb end
                function mod:create_slider(i) i=norm(i); if i.minimum_value==nil then i.minimum_value=0 end if i.maximum_value==nil then i.maximum_value=100 end if i.value==nil then i.value=i.minimum_value end local _cb=i.callback; i.callback=function(v) if _cb then pcall(_cb, v) end end if not M then return stub() end local ok,s=pcall(function() return M:create_slider(i) end); if not ok or not s then return stub() end s.update=function(_,v) pcall(function() s:set_percentage(tonumber(v) or i.minimum_value or 0) end) end s.SetValue=s.update return s end
                function mod:create_dropdown(i) i=norm(i); if type(i.options)~="table" then i.options={} end if not M then return stub() end local ok,d=pcall(function() return M:create_dropdown(i) end); if not ok or not d then return stub() end d.SetValue=function(_,a,b) pcall(function() d:update(b~=nil and b or a) end) end d.change_state=function(_,a,b) pcall(function() d:update(b~=nil and b or a) end) end d.set_options=NOP return d end
                function mod:create_textbox(i) i=norm(i); if not M then return stub() end local ok,t=pcall(function() return M:create_textbox(i) end); if not ok or not t then return stub() end t.update=function(_,v) pcall(function() t:update_text(tostring(v)) end) end t.SetValue=t.update return t end
                function mod:create_range_slider(i) i=i or {}; local dmin,dmax=i.minimum_value or i.minimum or 0, i.maximum_value or i.maximum or 100; if type(i.value)=="table" then dmin=i.value.min or dmin; dmax=i.value.max or dmax end local cb=i.callback; if not M then return stub() end local ok,s=pcall(function() return M:create_dual_slider({ title=i.title, flag=i.flag, minimum_value=i.minimum_value or i.minimum or 0, maximum_value=i.maximum_value or i.maximum or 100, min_value=dmin, max_value=dmax, round_number=i.round_number, suffix=i.suffix, callback=function(t) if cb then pcall(cb,t[1],t[2]) end end }) end); return (ok and s) or stub() end
                function mod:create_button(i) i=i or {}; if M then pcall(function() M:create_feature({ title=i.title or i.text or "Button", flag=i.flag or ("btn_"..tostring(i.title or math.random(1000000))), disablecheck=true, button_callback=function() if i.callback then pcall(i.callback) end end, callback=NOP }) end) end return stub() end
                function mod:create_keybind(i) i=i or {}; if M then pcall(function() M:create_feature({ title=i.title or "Keybind", flag=i.flag or ("key_"..tostring(i.title or math.random(1000000))), disablecheck=true, default=(typeof(i.default)=="EnumItem" and i.default.Name) or i.default or "Unknown", callback=function() if i.callback then pcall(i.callback) end end }) end) end return stub() end
                function mod:create_divider(i) if not M then return stub() end local ok,r=pcall(function() return M:create_divider(i or {}) end) return (ok and r) or stub() end
                function mod:create_paragraph(i) if not M then return stub() end local ok,r=pcall(function() return M:create_paragraph(i or {}) end) return (ok and r) or stub() end
                function mod:create_text(i) i=i or {}; if not M then return stub() end local ok,tm=pcall(function() return M:create_text(i) end); if not ok or not tm then return stub() end local c={} c.update=function(_,v) pcall(function() tm:Set({text=tostring(v)}) end) end c.SetValue=c.update return c end
                function mod:create_colorpicker(i) if not M then return stub() end local ok,r=pcall(function() return M:create_colorpicker(i or {}) end) return (ok and r) or stub() end
                return mod
            end
            return tab
        end
        function win:load() pcall(function() if not main._ui_loaded then main:load() end end) end
        win.Load = win.load
        function win:AutoLoad() end
        win.autoload = win.AutoLoad
        function win:Watermark() end
        function win:SetResizable() end
        function win:SetKeybind(k) pcall(function() local UIS=game:GetService("UserInputService"); local target=(typeof(k)=="EnumItem") and k or (type(k)=="string" and Enum.KeyCode[k]) or k; UIS.InputBegan:Connect(function(inp,gp) if gp then return end if inp.KeyCode==target then pcall(function() main:UIVisiblity() end) end end) end) end
        return win
    end
    return Library
end)()


-- Compat shim: legacy WindUI:Notify{...} routes through Stack UI.
local WindUI = {
    Notify = function(_, i)
        i = i or {}
        Library.SendNotification({ title = i.Title, text = i.Content, duration = i.Duration, icon = i.Icon })
    end,
}

local library = Library.new({ title = "Sapphire Private", PrimaryColor = Color3.fromRGB(48, 92, 200) })

-- ==== force-show the UI, independent of the engine ====
task.spawn(function()
    for _=1,200 do
        if library and library._native and library._native._ui_loaded then break end
        pcall(function() library:load() end)
        task.wait(0.1)
    end
end)

