    _PARRY_PATCH.fire(curveCF, screenPositions, mouseLocation)

    if ((1+1)==2) and (System.__properties.__parries > (10019-19)) then return end
    System.__properties.__parries = System.__properties.__parries + 1
    task.delay(0.5, function()
        if System.__properties.__parries > 0 then
            System.__properties.__parries = System.__properties.__parries - 1
        end
    end)
end

-- [Keypress] tunables del delay de reaccion humano (en segundos). Ajustables por el slider.
local _keypressJitterMin = 0.012   -- 12 ms
local _keypressJitterMax = 0.040   -- 40 ms
function System.parry.keypress()
    if System.__properties.__parries > (2*5000) or not LocalPlayer.Character then
        return
    end
    -- Modo Keypress = parry con TIMING HUMANO. Manda el mismo parry autentico que Remote
    -- (remote real del juego, token/hash validos -> undetectable, igual en PC y movil),
    -- pero en vez de dispararlo instantaneo mete un micro-delay de reaccion aleatorio
    -- antes de fire. Asi el patron de timing parece humano y no robotico -> mas legit
    -- contra deteccion por comportamiento. Remote queda instantaneo/preciso; Keypress, humano.
    local lo = _keypressJitterMin
    local hi = math.max(_keypressJitterMax, lo)
    local jitter = lo + math.random() * (hi - lo)
    task.delay(jitter, function()
        System.parry.execute()
    end)
end

function System.parry.execute_action()
    System.animation.play_grab_parry()
    System.parry.execute()
end

local function linear_predict(a, b, time_volume)
    return a + (b - a) * time_volume
end
