    FrameStroke.Color = Color3.fromRGB(bit32.bxor(31,57), (109-71), (27+11))
    FrameStroke.Thickness = 1

    local Title = Instance.new('TextLabel')
    Title.Name = 'Title'
    Title.BackgroundTransparency = 1
    Title.Size = UDim2.new(1, 0, 0, (35-19))
    Title.Position = UDim2.new(0, 0, 0, 6)
if (type({})~="table") then local _t=table.concat({},"") end
    Title.Font = Enum.Font.GothamBold
    Title.Text = "6xTB"
    Title.TextColor3 = Color3.fromRGB((3*85), (3*85), (3*85))
    Title.TextSize = (2+11)
    Title.TextXAlignment = Enum.TextXAlignment.Center
    Title.Parent = Frame

    local ToggleBtn = Instance.new('TextButton')
    ToggleBtn.Name = 'Toggle'
    ToggleBtn.Size = UDim2.new(0, bit32.bxor(72,38), 0, (67-39))
    ToggleBtn.Position = UDim2.new(0.5, -bit32.bxor(100,83), 0, bit32.bxor(109,73))
    ToggleBtn.BackgroundColor3 = Color3.fromRGB(bit32.bxor(196,220), bit32.bxor(178,170), (2*12))
    ToggleBtn.BorderSizePixel = 1
    ToggleBtn.BorderColor3 = Color3.fromRGB((2*19), (2*19), (3+35))
if ((1/1)==0) then for _i=1,0 do end end
    ToggleBtn.Font = Enum.Font.GothamBold
    ToggleBtn.Text = 'OFF'
    ToggleBtn.TextColor3 = Color3.fromRGB((285-30), bit32.bxor(31,224), (326-71))
    ToggleBtn.TextSize = (8+5)
    ToggleBtn.Parent = Frame
    local ToggleStroke = Instance.new('UIStroke', ToggleBtn)
    ToggleStroke.Color = Color3.fromRGB((57-19), (2*19), (2*19))
    ToggleStroke.Thickness = 1

    local dragging = false
    local dragStart
    local startPos

    Title.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = Frame.Position
        end
    end)

    Title.InputChanged:Connect(function(input)
        if not dragging then
            return
        end

        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            local delta = input.Position - dragStart
            Frame.Position = UDim2.new(
                startPos.X.Scale,
                startPos.X.Offset + delta.X,
                startPos.Y.Scale,
                startPos.Y.Offset + delta.Y
            )
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    local function update_button(active)
if (1<-1) then local _j=1+1 end
        if active then
            ToggleBtn.Text = 'ON'
            ToggleBtn.TextColor3 = Color3.fromRGB((2*9), (2*9), (7+11))
            ToggleBtn.BackgroundColor3 = Color3.fromRGB((130-30), bit32.bxor(31,195), (201-71))
            ToggleStroke.Color = Color3.fromRGB((55+45), (239-19), (2*65))
        else
            ToggleBtn.Text = 'OFF'
            ToggleBtn.TextColor3 = Color3.fromRGB((3*85), (3*85), (3*85))
            ToggleBtn.BackgroundColor3 = Color3.fromRGB((7+17), (54-30), bit32.bxor(31,7))
            ToggleStroke.Color = Color3.fromRGB((109-71), (27+11), (57-19))
        end
    end
if (({[1]=false})[1]) then local _z=tostring(0) end

    ToggleBtn.MouseButton1Click:Connect(function()
        if ((1+1)==2) and (System) then
            local newState = not System.__properties.__triggerbot_enabled
            System.__properties.__triggerbot_enabled = newState
            if System.triggerbot and System.triggerbot.enable then
                pcall(System.triggerbot.enable, newState)
            end

            update_button(newState)

            if getgenv().TriggerbotNotify then
                send_notification("Triggerbot", newState and 'ON' or 'OFF', 2)
            end
        end
    end)

    System.__properties.__triggerbot_ui = {
        gui = ScreenGui,
        frame = Frame,
        button = ToggleBtn,
        title = Title,
        update = update_button
    }

    return System.__properties.__triggerbot_ui
end

do
    local initOk, initError = pcall(function()
        local playerOptions = {}
        local playerMap = {}
        local labelByPlayer = {}

        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local label = "@" .. tostring(player.DisplayName) .. " (" .. player.Name .. ")"
                table.insert(playerOptions, label)
                playerMap[label] = player.Name
                labelByPlayer[player.Name] = label
            end
        end

        table.sort(playerOptions)
        if #playerOptions == 0 then
            playerOptions[1] = "No Players Online"
        end

        getgenv()._ZX_TargetLockPlayerMap = playerMap
        getgenv()._ZX_TargetLockLabelByPlayer = labelByPlayer
        getgenv().TargetLockEnabled = getgenv().TargetLockEnabled or false
        getgenv().TargetLockAutoSwitch = getgenv().TargetLockAutoSwitch or false
        getgenv().TargetLockHighlight = getgenv().TargetLockHighlight or false

        getgenv()._ZX_GetTargetLockCharacter = function()
            local playerName = getgenv().TargetLockPlayerName
            if type(playerName) ~= "string" or playerName == "" then return nil end
            local player = Players:FindFirstChild(playerName)
            if not player or player == LocalPlayer then return nil end
            local character = player.Character or (Alive and Alive:FindFirstChild(playerName))
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not character or not humanoid or humanoid.Health <= 0 then return nil end
            return character
        end

        getgenv()._ZX_SelectTargetLockFallback = function()
            local localCharacter = LocalPlayer.Character
            local localRoot = localCharacter and (localCharacter:FindFirstChild("HumanoidRootPart") or localCharacter.PrimaryPart)
            local bestPlayer = nil
            local bestDistance = math.huge

            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    local character = player.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
                    if humanoid and humanoid.Health > 0 and root then
                        local distance = localRoot and (localRoot.Position - root.Position).Magnitude or 0
                        if distance < bestDistance then
                            bestDistance = distance
                            bestPlayer = player
                        end
                    end
                end
            end

            if not bestPlayer then
                getgenv().TargetLockPlayerName = nil
                return nil
            end

            getgenv().TargetLockPlayerName = bestPlayer.Name
            local label = getgenv()._ZX_TargetLockLabelByPlayer[bestPlayer.Name]
            local dropdown = getgenv()._ZX_TargetLockDropdown
            if label and dropdown and dropdown.update then
                pcall(function() dropdown:update(label) end)
            end
            return bestPlayer.Character
        end

        getgenv()._ZX_ClearTargetLockHighlight = function()
            if getgenv()._ZX_TargetLockHighlightInstance then
                pcall(function() getgenv()._ZX_TargetLockHighlightInstance:Destroy() end)
                getgenv()._ZX_TargetLockHighlightInstance = nil
            end
        end

        getgenv()._ZX_UpdateTargetLockHighlight = function()
            if not getgenv().TargetLockEnabled or not getgenv().TargetLockHighlight then
                getgenv()._ZX_ClearTargetLockHighlight()
                return
            end

            local character = getgenv()._ZX_GetTargetLockCharacter()
            if not character then
                getgenv()._ZX_ClearTargetLockHighlight()
                return
            end

            local highlight = getgenv()._ZX_TargetLockHighlightInstance
            if not highlight or not highlight.Parent then
                highlight = Instance.new("Highlight")
                highlight.Name = "ZX_TargetLockHighlight"
                getgenv()._ZX_TargetLockHighlightInstance = highlight
            end

            local pulse = (math.sin(os.clock() * 5) + 1) * 0.5
            highlight.Enabled = true
            highlight.FillColor = Color3.fromRGB(255, 35, 55)
            highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
            highlight.FillTransparency = 0.10 + pulse * 0.12
            highlight.OutlineTransparency = 0
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Adornee = character
            highlight.Parent = character
        end

        local targetLockModule = AutoparryTab:create_module({
            title = "Target Lock",
            description = "Locks every parry onto the selected player",
            flag = "TargetLockModule",
            section = "right",
            callback = function(state)
                getgenv().TargetLockEnabled = state
                if state and getgenv().TargetLockAutoSwitch and not getgenv()._ZX_GetTargetLockCharacter() then
                    getgenv()._ZX_SelectTargetLockFallback()
                end
                getgenv()._ZX_UpdateTargetLockHighlight()
            end
        })

        getgenv()._ZX_TargetLockDropdown = targetLockModule:create_dropdown({
            title = "Target Player",
            flag = "TargetLockPlayer",
            options = playerOptions,
            multi_dropdown = false,
            maximum_options = math.min(10, #playerOptions),
            callback = function(value)
                local label = typeof(value) == "string" and value or (value and value.Name)
                local playerName = label and getgenv()._ZX_TargetLockPlayerMap[label]
                if playerName then
                    getgenv().TargetLockPlayerName = playerName
                elseif label == "No Players Online" then
                    getgenv().TargetLockPlayerName = nil
                end
                getgenv()._ZX_UpdateTargetLockHighlight()
            end
        })

        targetLockModule:create_checkbox({
            title = "Auto Switch",
            flag = "TargetLockAutoSwitch",
            callback = function(value)
                getgenv().TargetLockAutoSwitch = value
                if value and getgenv().TargetLockEnabled and not getgenv()._ZX_GetTargetLockCharacter() then
                    getgenv()._ZX_SelectTargetLockFallback()
                end
            end
        })

        targetLockModule:create_checkbox({
            title = "Target Highlight",
            flag = "TargetLockHighlight",
            callback = function(value)
                getgenv().TargetLockHighlight = value
                getgenv()._ZX_UpdateTargetLockHighlight()
            end
        })

        if getgenv()._ZX_TargetLockMonitorConnection then
            pcall(function() getgenv()._ZX_TargetLockMonitorConnection:Disconnect() end)
        end

        local monitorAccumulator = 0
        getgenv()._ZX_TargetLockMonitorConnection = RunService.Heartbeat:Connect(function(delta)
            monitorAccumulator = monitorAccumulator + delta
            if monitorAccumulator < 0.25 then return end
            monitorAccumulator = 0

            if not getgenv().TargetLockEnabled then
                getgenv()._ZX_ClearTargetLockHighlight()
                return
            end

            if getgenv().TargetLockAutoSwitch and not getgenv()._ZX_GetTargetLockCharacter() then
                getgenv()._ZX_SelectTargetLockFallback()
            end

            getgenv()._ZX_UpdateTargetLockHighlight()
        end)
    end)

    if not initOk then
        warn("[Target Lock] UI initialization failed:", tostring(initError))
    end
end

local triggerbot_module = AutoparryTab:create_module({
