    nameSpoofMod:create_textbox({
        title = "Spoofed Name",
        placeholder = "Enter fake name...",
        flag = "ZX_SpoofedNameText",
        callback = function(value)
            CONFIG.FakeName = value
            CONFIG.FakeDisplay = value
            TargetName = value
